import { toJSONSchema, type ZodType } from 'zod';

/**
 * Converts a Zod schema to a Schema Object in the Contract Document's OpenAPI 3.0 dialect
 * (contract-document.md §4.2), for use as a topic's request/response payload schema in the benzene spec /
 * Contract Document.
 *
 * TypeScript-only file with no direct C# counterpart. In `Benzene.Schema.OpenApi` the payload schema is
 * generated by *reflecting* over the request/response CLR type; TypeScript erases types at runtime, so the
 * schema is instead derived from the runtime Zod schema the service already registered to validate that
 * type (`ZodSchemaRegistry`). Because a Zod schema encodes both the shape *and* the validation rules, one
 * conversion yields both.
 *
 * Zod 4's native `z.toJSONSchema` does the conversion, with:
 * - `target: 'openapi-3.0'` — the dialect the document declares (`schemaDialect: "openapi-3.0"`): a nullable
 *   value is `nullable: true`, never a `type` array or an `anyOf` with `null`;
 * - `io: 'input'` — the shape a sender writes, which is what a request contract constrains: a transformed
 *   field is described by the type it is written as, not the type a transform produces;
 * - `unrepresentable: 'any'` — a field Zod cannot express (e.g. `z.bigint()`) becomes `{}` rather than
 *   throwing, so one exotic field never fails a whole service's spec; a `z.date()` is described as the
 *   RFC 3339 string it marshals to (`{"type":"string","format":"date-time"}`).
 *
 * The output is then brought to the derivation table's exact shapes:
 * - `required` lists every property the marshaled object always carries (contract-document.md §4.2): one
 *   that is required on input, and also one with a declared default (`.default()`, `.prefault()`,
 *   `.catch()`), because the type a service handles (`z.infer`, the output) always has it, so its JSON
 *   always does. `io: 'input'` alone would leave a defaulted property optional - `required` describes the
 *   payload as written, not what a sender may leave out. A property optional on both sides (`.optional()`,
 *   `.default(v).optional()`) stays optional;
 * - named sub-schemas (`.meta({ id })`) are returned under `$defs`, referenced as `#/$defs/<id>`, and a
 *   recursive reference to the root stays `#` — `SchemaBuilder` hoists them into `components.schemas`;
 * - a nullable object or enum becomes the wrapper `{"type":<T's type>,"nullable":true,"allOf":[T]}`
 *   (contract-document.md §4.2), whether `T` is a `$ref` or inline — Zod writes a nullable reference
 *   without a `type`, which OpenAPI 3.0.3 would ignore, and merges `nullable` into an inline object;
 * - the `±Number.MAX_SAFE_INTEGER` bounds Zod adds to every `.int()` are dropped: they are a property of
 *   JavaScript numbers, not a rule the service declared;
 * - the root `$schema` marker is stripped (the schema is a fragment of a larger document).
 */
export function zodToJsonSchema(schema: ZodType): Record<string, unknown> {
  const json = toJSONSchema(schema, {
    target: 'openapi-3.0',
    io: 'input',
    unrepresentable: 'any',
    override: (context) => {
      const def = (context.zodSchema as unknown as ZodInternals)._zod?.def;
      if (def?.type === 'date') {
        context.jsonSchema.type = 'string';
        context.jsonSchema.format = 'date-time';
      } else if (def?.type === 'object' && def.shape !== undefined) {
        const required = alwaysEmitted(def.shape);
        if (required.length > 0) {
          context.jsonSchema.required = required;
        } else {
          delete context.jsonSchema.required;
        }
      }
    },
  }) as Record<string, unknown>;

  const { $schema: _dialect, definitions, ...root } = json;
  const defs = isObject(definitions) ? definitions : {};

  const typeOfRef = (ref: string): unknown => {
    if (ref === '#') {
      return root['type'];
    }
    const target = defs[ref.replace(/^#\/(definitions|\$defs)\//, '')];
    return isObject(target) ? target['type'] : undefined;
  };

  const result = normalize(root, typeOfRef) as Record<string, unknown>;
  const names = Object.keys(defs);
  if (names.length > 0) {
    const hoisted: Record<string, unknown> = {};
    for (const name of names) {
      hoisted[name] = normalize(defs[name], typeOfRef);
    }
    result['$defs'] = hoisted;
  }
  return result;
}

/** The slice of Zod 4's internals the override reads: the node's kind, an object's shape, and optionality. */
interface ZodInternals {
  _zod?: {
    def?: { type?: string; shape?: Record<string, ZodInternals> };
    /** `'optional'` when the property may be absent from the input (`.optional()`, `.default()`, ...). */
    optin?: 'optional';
    /** `'optional'` when the property may be absent from the output - the parsed value the service holds. */
    optout?: 'optional';
  };
}

/**
 * The properties of an object shape the marshaler always emits, in shape order (contract-document.md §4.2):
 * required on input, or present on output whatever the input was (a declared default).
 */
function alwaysEmitted(shape: Record<string, ZodInternals>): string[] {
  return Object.keys(shape).filter((name) => {
    const property = shape[name]?._zod;
    return property?.optin !== 'optional' || property?.optout !== 'optional';
  });
}

const MaxSafe = Number.MAX_SAFE_INTEGER;

function normalize(node: unknown, typeOfRef: (ref: string) => unknown): unknown {
  if (!isObject(node)) {
    return node;
  }

  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(node)) {
    if (key === '$ref' && typeof value === 'string') {
      out[key] = value.replace(/^#\/definitions\//, '#/$defs/');
    } else if (key === 'properties' && isObject(value)) {
      const properties: Record<string, unknown> = {};
      for (const [name, property] of Object.entries(value)) {
        properties[name] = normalize(property, typeOfRef);
      }
      out[key] = properties;
    } else if ((key === 'items' || key === 'additionalProperties' || key === 'not') && isObject(value)) {
      out[key] = normalize(value, typeOfRef);
    } else if ((key === 'allOf' || key === 'anyOf' || key === 'oneOf') && Array.isArray(value)) {
      out[key] = value.map((member) => normalize(member, typeOfRef));
    } else {
      out[key] = value;
    }
  }

  if (out['type'] === 'integer') {
    if (out['minimum'] === -MaxSafe) delete out['minimum'];
    if (out['maximum'] === MaxSafe) delete out['maximum'];
  }

  if (out['nullable'] === true) {
    const allOf = out['allOf'];
    // Zod's nullable reference: `{nullable, allOf:[{$ref}]}` without a `type`.
    if (Array.isArray(allOf) && allOf.length === 1 && isObject(allOf[0]) && typeof allOf[0]['$ref'] === 'string') {
      const type = typeOfRef(allOf[0]['$ref'] as string);
      return type === undefined ? out : { type, ...out };
    }
    // An inline nullable object or enum: Zod merges `nullable` into it; §4.2 wraps it.
    const isRecord = out['type'] === 'object' && !(isObject(out['additionalProperties']) && out['properties'] === undefined);
    if (isRecord || Array.isArray(out['enum'])) {
      const { nullable: _nullable, ...inner } = out;
      if (Array.isArray(inner['enum'])) {
        inner['enum'] = inner['enum'].filter((value) => value !== null);
      }
      const wrapper: Record<string, unknown> = { nullable: true, allOf: [inner] };
      return inner['type'] === undefined ? wrapper : { type: inner['type'], ...wrapper };
    }
  }
  return out;
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}
